import json

# Fix downsample with proper list handling
def downsample(grid, factor):
    h, w = len(grid), len(grid[0])
    new_h, new_w = (h + factor - 1) // factor, (w + factor - 1) // factor
    result = []
    for r in range(new_h):
        row = []
        for c in range(new_w):
            block = []
            for rr in range(r*factor, min((r+1)*factor, h)):
                for cc in range(c*factor, min((c+1)*factor, w)):
                    block.append(grid[rr][cc])
            # mode
            counts = {}
            for val in block:
                counts[val] = counts.get(val, 0) + 1
            row.append(max(counts.keys(), key=lambda k: counts[k]))
        result.append(row)
    return result

